namespace sitesplat\bblivechat;
class ext extends \phpbb\extension\base { protected $db, $config, $module, $container, $fs; protected $parent_id = 0; public function __construct($container, $extension_finder, $migrator, $extension_name, $extension_path) { $this->db = $container->get('dbal.conn'); $this->config = $container->get('config'); $this->module = $container->get('module.manager'); $this->container = $container; } public function is_enableable() { if (!function_exists('\sitesplat\fs_instance') || $this->db->get_sql_layer() != 'mysqli' || !extension_loaded('mbstring') || $this->config['session_length'] < 1800) { return false; } $this->fs = \sitesplat\fs_instance(); $this->fs->init(); if (!$this->fs->fs_type) { return false; } $sql = 'SELECT module_id FROM ' . MODULES_TABLE . " WHERE module_class = 'acp' AND module_langname = 'SiteSplat'"; $result = $this->db->sql_query($sql); $this->parent_id = (int) $this->db->sql_fetchfield('module_id'); $this->db->sql_freeresult($result); return $this->parent_id > 0; } public function enable_step($whocares) { $data = [ 'module_basename' => '', 'module_enabled' => 1, 'module_display' => 1, 'module_class' => 'acp', 'parent_id' => $this->parent_id, 'module_langname' => 'BBlivechat', ]; $this->module->update_module_data($data); $ac_id = $data['module_id']; $this->module->move_module_by($data, 'acp', 'move_up', 1); $data = [ 'module_basename' => '\sitesplat\bblivechat\acp\chat_module', 'module_enabled' => 1, 'module_display' => 1, 'module_class' => 'acp', 'parent_id' => $ac_id, 'module_langname' => 'BBLIVECHAT_SETTINGS', 'module_mode' => 'settings', 'module_auth' => 'acl_a_board', ]; $this->module->update_module_data($data); if ($this->config['bblivechat_installed']) { $data = [ 'module_basename' => '\sitesplat\bblivechat\acp\chat_module', 'module_enabled' => 1, 'module_display' => 1, 'module_class' => 'acp', 'parent_id' => $ac_id, 'module_langname' => 'BBLIVECHAT_ROOMS', 'module_mode' => 'rooms', 'module_auth' => 'acl_a_board', ]; $this->module->update_module_data($data); $data = [ 'module_basename' => '\sitesplat\bblivechat\acp\chat_module', 'module_enabled' => 1, 'module_display' => 1, 'module_class' => 'acp', 'parent_id' => $ac_id, 'module_langname' => 'VIEW_FORUM_LOGS', 'module_mode' => 'logs', 'module_auth' => 'acl_a_board', ]; $this->module->update_module_data($data); } $result = $this->db->sql_query("SELECT support FROM INFORMATION_SCHEMA.ENGINES WHERE engine LIKE 'innodb' AND support IN ('yes','default')"); $innodb = (string) $this->db->sql_fetchfield('support'); $this->db->sql_freeresult($result); if ($innodb) { $innodb = "ENGINE=InnoDB"; } $this->db->sql_query( "CREATE TABLE IF NOT EXISTS bblc_bans ( userID int(11) UNSIGNED NOT NULL, userName varchar(64) COLLATE utf8_bin NOT NULL, `dateTime` datetime NOT NULL, ip varchar(64) COLLATE utf8_bin NOT NULL DEFAULT '', PRIMARY KEY (userID), KEY userName (userName), KEY `dateTime` (`dateTime`) ) DEFAULT CHARSET=utf8 COLLATE=utf8_bin"); $this->db->sql_query( "CREATE TABLE IF NOT EXISTS bblc_invitations ( userID int(11) UNSIGNED NOT NULL, channel int(11) NOT NULL, `dateTime` datetime NOT NULL, PRIMARY KEY (userID,channel), KEY `dateTime` (`dateTime`) ) DEFAULT CHARSET=utf8 COLLATE=utf8_bin"); $this->db->sql_query( "CREATE TABLE IF NOT EXISTS bblc_messages ( id int(11) UNSIGNED NOT NULL AUTO_INCREMENT, userID int(11) UNSIGNED NOT NULL, userName varchar(64) COLLATE utf8_bin NOT NULL, userRole tinyint(1) UNSIGNED NOT NULL, channel int(11) NOT NULL, `dateTime` datetime NOT NULL, ip varchar(255) COLLATE utf8_bin NOT NULL DEFAULT '', `text` text COLLATE utf8_bin, PRIMARY KEY (id), KEY message_condition (id,channel,`dateTime`), KEY mchannel (channel), KEY `dateTime` (`dateTime`) ) $innodb DEFAULT CHARSET=utf8 COLLATE=utf8_bin"); $this->db->sql_query( "CREATE TABLE IF NOT EXISTS bblc_online ( userID int(11) UNSIGNED NOT NULL, userName varchar(64) COLLATE utf8_bin NOT NULL, userRole tinyint(1) UNSIGNED NOT NULL, channel int(11) NOT NULL, `dateTime` datetime NOT NULL, ip varchar(255) COLLATE utf8_bin NOT NULL DEFAULT '', PRIMARY KEY (userID), KEY ochannel (channel), KEY userName (userName) ) $innodb DEFAULT CHARSET=utf8 COLLATE=utf8_bin"); return false; } public function disable_step($whocares) { $ids = []; $sql = 'SELECT module_id FROM ' . MODULES_TABLE . " WHERE module_class = 'acp' AND module_langname IN ('BBlivechat','BBLIVECHAT_SETTINGS','BBLIVECHAT_ROOMS','VIEW_FORUM_LOGS') ORDER BY left_id DESC"; $result = $this->db->sql_query($sql); while ($row = $this->db->sql_fetchrow($result)) { $ids[] = (int) $row['module_id']; } $this->db->sql_freeresult($result); if (!count($ids)) { return false; } foreach ($ids as $module_id) { try { $this->module->delete_module($module_id, 'acp'); } catch (\phpbb\module\exception\module_exception $exception) { } } return false; } public function purge_step($whocares) { $this->db->sql_query('DROP TABLE IF EXISTS bblc_bans'); $this->db->sql_query('DROP TABLE IF EXISTS bblc_invitations'); $this->db->sql_query('DROP TABLE IF EXISTS bblc_messages'); $this->db->sql_query('DROP TABLE IF EXISTS bblc_online'); $this->db->sql_query('DELETE FROM ' . CONFIG_TEXT_TABLE . " WHERE config_name = 'bblivechat'"); $this->config->delete('bblivechat_installed'); $this->config->delete('bblivechat_cron'); if (function_exists('\sitesplat\fs_instance')) { $fs = \sitesplat\fs_instance(); $fs->init(); $fs->rmrf($fs->phpbb_root_dir . '/bblivechat'); } return false; } }